 void accentSettings(){LinearLayout panel=column();panel.setPadding(dp(20),dp(10),dp(20),dp(10));View preview=new View(this);panel.addView(preview,new LinearLayout.LayoutParams(-1,dp(48)));int c=accent();int[] values={Color.red(c),Color.green(c),Color.blue(c)};String[] labels={"الأحمر","الأخضر","الأزرق"};preview.setBackground(glass(c,12));for(int i=0;i<3;i++){final int k=i;panel.addView(new TextView(this){{setText(labels[k]);}});SeekBar bar=new SeekBar(this);bar.setMax(255);bar.setProgress(values[i]);panel.addView(bar);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){values[k]=p;preview.setBackground(glass(Color.rgb(values[0],values[1],values[2]),12));}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});}new AlertDialog.Builder(this).setTitle("لون التمييز").setView(panel).setPositiveButton("حفظ",(d,n)->{prefs.edit().putInt("customAccent",Color.rgb(values[0],values[1],values[2])).apply();recreate();}).setNeutralButton("افتراضي",(d,n)->{prefs.edit().remove("customAccent").apply();recreate();}).setNegativeButton("إلغاء",null).show();}
