String[] clockNames={"دائرية سوداء","دائرية فضية","دائرية زرقاء","مربعة سوداء","مربعة فضية","مربعة زرقاء","رقمية أفقية","رقمية عمودية","RETRO LED","FLIP CLOCK","MINIMAL WHITE","LUXURY GOLD"};
int clockStyle(){return Math.max(0,Math.min(clockNames.length-1,prefs.getInt("clockStyleV2",Math.min(2,prefs.getInt("clockStyle",0)))));}
void clockSettings(){new AlertDialog.Builder(this).setTitle("BECHIR CLOCK STUDIO").setItems(new String[]{"اختيار التصميم","لون الأرقام والعقارب","حجم الساعة","نظام الوقت","إظهار أو إخفاء الثواني","استعادة إعدادات الساعة"},(d,n)->{if(n==0){new AlertDialog.Builder(this).setTitle("تصميم الساعة").setSingleChoiceItems(clockNames,clockStyle(),(dialog,i)->{prefs.edit().putInt("clockStyleV2",i).apply();dialog.dismiss();render();}).show();}else if(n==1){new AlertDialog.Builder(this).setTitle("لون الساعة").setSingleChoiceItems(new String[]{"تلقائي","أبيض","أسود","ذهبي","أزرق","أخضر","أحمر"},prefs.getInt("clockInk",0),(dialog,i)->{prefs.edit().putInt("clockInk",i).apply();dialog.dismiss();render();}).show();}else if(n==2){new AlertDialog.Builder(this).setTitle("حجم الساعة").setSingleChoiceItems(new String[]{"صغير","قياسي","كبير"},prefs.getInt("clockSize",1),(dialog,i)->{prefs.edit().putInt("clockSize",i).apply();dialog.dismiss();render();}).show();}else if(n==3){new AlertDialog.Builder(this).setTitle("نظام الوقت").setSingleChoiceItems(new String[]{"24 ساعة","12 ساعة"},prefs.getBoolean("clock12",false)?1:0,(dialog,i)->{prefs.edit().putBoolean("clock12",i==1).apply();dialog.dismiss();render();}).show();}else if(n==4){prefs.edit().putBoolean("clockSeconds",!prefs.getBoolean("clockSeconds",true)).apply();render();}else{prefs.edit().putInt("clockStyleV2",0).remove("clockInk").remove("clockSize").remove("clock12").remove("clockSeconds").apply();render();}}).show();}
 class BatteryRing extends View{int level;Paint p=new Paint(3);BatteryRing(int n){super(MainActivity.this);level=n;}protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)-dp(5);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(3));p.setColor(0xffcccccc);c.drawCircle(x,y,r,p);p.setColor(accent());p.setStrokeCap(Paint.Cap.ROUND);c.drawArc(x-r,y-r,x+r,y+r,-90,level*3.6f,false,p);p.setStyle(Paint.Style.FILL);p.setColor(ink());p.setTextSize(dp(12));p.setTextAlign(Paint.Align.CENTER);c.drawText(level+"%",x,y+dp(4),p);}}
 class OrbitClock extends View {
 final Paint p=new Paint(3); final Calendar now=Calendar.getInstance(); final int style=clockStyle(); final boolean seconds=prefs.getBoolean("clockSeconds",true), twelve=prefs.getBoolean("clock12",false); final int[] colors={0,Color.WHITE,0xff222222,0xffe8b95e,0xff3984f5,0xff62f5ad,0xffe84d58}; final int selected=Math.max(0,Math.min(6,prefs.getInt("clockInk",0))); final int[] segments={63,6,91,79,102,109,125,7,127,111};
 OrbitClock(){super(MainActivity.this);}
 void hand(Canvas c,float angle,float length,float width,int color){p.setColor(color);p.setStrokeWidth(width);p.setStrokeCap(Paint.Cap.ROUND);double a=Math.toRadians(angle);c.drawLine(0,0,(float)Math.sin(a)*length,-(float)Math.cos(a)*length,p);}
 void txt(Canvas c,String t,float x,float y,float size,int color){p.setStyle(Paint.Style.FILL);p.setColor(color);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(size);c.drawText(t,x,y,p);}
 void digit(Canvas c,int d,float x,float y,int color){int[][] seg={{4,0,26,4},{27,5,31,27},{27,32,31,54},{4,55,26,59},{0,32,4,54},{0,5,4,27},{4,28,26,32}};for(int j=0;j<7;j++){p.setColor((segments[d]&(1<<j))!=0?color:0xff23332c);int[] q=seg[j];c.drawRoundRect(x+q[0],y+q[1],x+q[2],y+q[3],1,1,p);}}
 protected void onDraw(Canvas c){super.onDraw(c);float r=Math.min(getWidth(),getHeight())*.46f;if(r<=0)return;now.setTimeInMillis(System.currentTimeMillis());int h=now.get(Calendar.HOUR_OF_DAY),m=now.get(Calendar.MINUTE),sec=now.get(Calendar.SECOND);int shown=twelve?(h%12==0?12:h%12):h;c.save();c.translate(getWidth()/2f,getHeight()/2f);c.scale(r/100,r/100);p.setStyle(Paint.Style.FILL);p.setTypeface(Typeface.create("sans-serif-medium",0));if(style<6){int k=style%3;boolean square=style>=3;int base=k==0?0xff161616:k==1?0xffbbbbbb:0xff102235;int light=k==0?0xff303030:k==1?0xffeeeeee:0xff29496b;int fg=selected==0?(k==1?0xff222222:Color.WHITE):colors[selected];p.setShader(new RadialGradient(0,0,100,new int[]{light,base},null,Shader.TileMode.CLAMP));if(square)c.drawRoundRect(-100,-100,100,100,24,24,p);else c.drawCircle(0,0,100,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);p.setColor(0xffbcbcbc);if(square)c.drawRoundRect(-96,-96,96,96,22,22,p);else c.drawCircle(0,0,97,p);p.setStrokeWidth(2);p.setColor(accent());c.drawCircle(0,0,91,p);p.setStyle(Paint.Style.FILL);for(int i=0;i<60;i++){double t=i*Math.PI/30;float x=(float)Math.sin(t),y=-(float)Math.cos(t);p.setColor(fg);p.setStrokeWidth(i%5==0?2:1);c.drawLine(x*(i%5==0?85:89),y*(i%5==0?85:89),x*92,y*92,p);}for(int i=1;i<=12;i++){double t=i*Math.PI/6;txt(c,""+i,(float)Math.sin(t)*73,-(float)Math.cos(t)*73+5,14,fg);}txt(c,"BECHIR ULTRA",0,-29,8,fg);hand(c,(h%12+m/60f)*30,48,5,fg);hand(c,(m+sec/60f)*6,65,3,fg);if(seconds)hand(c,sec*6,79,1.4f,accent());p.setColor(accent());c.drawCircle(0,0,4,p);}else{int base=style==10?0xffeeeeee:style==9?0xff30223f:0xff111111;int fg=selected!=0?colors[selected]:style==10?0xff222222:style==11?0xffe8b95e:style==8?0xff62f5ad:Color.WHITE;p.setColor(base);c.drawRoundRect(-100,-85,100,85,22,22,p);String hh=String.format(Locale.US,"%02d",shown),mm=String.format(Locale.US,"%02d",m);if(style==7){txt(c,hh,0,-8,65,fg);txt(c,mm,0,59,65,fg);}else if(style==8){digit(c,shown/10,-80,-30,fg);digit(c,shown%10,-43,-30,fg);digit(c,m/10,12,-30,fg);digit(c,m%10,49,-30,fg);p.setColor(fg);c.drawCircle(0,-12,3,p);c.drawCircle(0,12,3,p);}else if(style==9){p.setColor(0xff50405f);c.drawRoundRect(-91,-38,-4,35,9,9,p);c.drawRoundRect(4,-38,91,35,9,9,p);txt(c,hh,-48,15,48,fg);txt(c,mm,48,15,48,fg);p.setColor(0xff30223f);p.setStrokeWidth(1);c.drawLine(-91,0,-4,0,p);c.drawLine(4,0,91,0,p);}else txt(c,hh+":"+mm,0,15,56,fg);if(style!=7)txt(c,clockNames[style],0,-55,10,fg);if(seconds||twelve)txt(c,(seconds?String.format(Locale.US,"%02d",sec):"")+(twelve?(h<12?" AM":" PM"):""),0,style==7?77:61,12,fg);}c.restore();if(isShown())postInvalidateDelayed(seconds?1000:60000-System.currentTimeMillis()%60000);}
 }
class DockIcon extends View {int k;Paint p=new Paint(3);DockIcon(int n){super(MainActivity.this);k=n;}protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/48f,getHeight()/48f);p.setColor(0xffe4efff);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2.8f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);if(k==0){Path a=new Path();a.moveTo(13,7);a.lineTo(21,16);a.lineTo(16,22);a.quadTo(20,30,27,33);a.lineTo(33,27);a.lineTo(41,35);a.quadTo(39,44,30,41);a.quadTo(10,34,7,15);a.close();c.drawPath(a,p);}else if(k==1){c.drawRoundRect(6,9,42,34,8,8,p);c.drawLine(14,34,10,41,p);c.drawLine(10,41,23,34,p);for(int i=0;i<3;i++)c.drawCircle(15+i*9,22,1,p);}else if(k==2){c.drawRoundRect(5,13,43,39,6,6,p);c.drawLine(16,13,20,7,p);c.drawLine(20,7,29,7,p);c.drawLine(29,7,33,13,p);c.drawCircle(24,26,8,p);}else{c.drawCircle(24,24,18,p);c.drawOval(15,6,33,42,p);c.drawLine(6,24,42,24,p);}c.restore();}}
